            if (payload?.chart?.error || !Array.isArray(rows) || rows.length !== 1) return CFRsiTargets.failure_("Yahoo RSI2 chart is unavailable", source);
            const chart = rows[0], meta = chart?.meta;
            if (!meta || typeof meta.symbol !== "string" || meta.symbol.toUpperCase() !== requestedSymbol) return CFRsiTargets.failure_("Yahoo RSI2 chart returned a different ticker", source);
            const price = CFRsiTargets.number_(meta.regularMarketPrice, true), config = CFRsiTargets.dateConfig_(meta), sessionDate = CFRsiTargets.day_(meta.regularMarketTime, config);
            if (price === null || !sessionDate) return CFRsiTargets.failure_("Yahoo quote price, time or exchange session is unavailable", source);
            const history = CFRsiTargets.history_(chart, sessionDate, config), bars = chart.indicators?.quote?.[0] || {}, index = history.currentBar;
            const bar = (field, positive = false) => Array.isArray(bars[field]) && index >= 0 ? CFRsiTargets.number_(bars[field][index], positive) : null;
            return { ok: true, status: history.error ? "Quote available; RSI2 history unavailable" : "Available", symbol: requestedSymbol, source,
                quoteTime: new Date(meta.regularMarketTime * 1000).toISOString(), sessionDate, dateConfig: config,
                price, open: bar("open", true), low: CFRsiTargets.number_(meta.regularMarketDayLow, true) ?? bar("low", true),
                high: CFRsiTargets.number_(meta.regularMarketDayHigh, true) ?? bar("high", true), volume: CFRsiTargets.number_(meta.regularMarketVolume) ?? bar("volume"),
                previousClose: history.previousClose, averageGain: history.averageGain, averageLoss: history.averageLoss, historyError: history.error };
